package solution

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"math"
	"strings"
	"testing"
)

func signRawPayload(t *testing.T, payload []byte, secret []byte) string {
	t.Helper()
	encoded := base64.RawURLEncoding.EncodeToString(payload)
	mac := hmac.New(sha256.New, secret)
	_, _ = mac.Write([]byte(encoded))
	signature := base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
	return encoded + "." + signature
}

func TestSessionCredentialRoundTripAndDeterminism(t *testing.T) {
	secret := []byte("correct horse battery staple")
	token1, err := GenerateSessionCredential("subject-1", "a@example.com", secret, 100)
	if err != nil {
		t.Fatal(err)
	}
	token2, err := GenerateSessionCredential("subject-1", "a@example.com", secret, 100)
	if err != nil || token1 != token2 {
		t.Fatalf("generation not deterministic: %q %q %v", token1, token2, err)
	}
	secret[0] = 'X'
	claims, err := VerifySessionCredential(token1, []byte("correct horse battery staple"), 100)
	if err != nil {
		t.Fatalf("VerifySessionCredential: %v", err)
	}
	want := SessionClaims{Subject: "subject-1", Contact: "a@example.com", IssuedAt: 100, ExpiresAt: 86500}
	if claims != want {
		t.Fatalf("claims = %#v, want %#v", claims, want)
	}
	if _, err := VerifySessionCredential(token1, []byte("correct horse battery staple"), 86499); err != nil {
		t.Fatalf("last valid second rejected: %v", err)
	}
	if _, err := VerifySessionCredential(token1, []byte("correct horse battery staple"), 86500); err == nil {
		t.Fatal("token accepted at exact expiration")
	}
	if _, err := VerifySessionCredential(token1, []byte("correct horse battery staple"), 99); err == nil {
		t.Fatal("token accepted before issuance")
	}
	if _, err := VerifySessionCredential(token1, []byte("correct horse battery staple"), -1); err == nil {
		t.Fatal("token accepted with negative current time")
	}
}

func TestGenerateSessionCredentialValidation(t *testing.T) {
	cases := []struct {
		subject string
		contact string
		secret  []byte
		issued  int64
	}{
		{"", "c", []byte("s"), 0},
		{"s", "", []byte("s"), 0},
		{"s", "c", nil, 0},
		{"s", "c", []byte("s"), -1},
		{"s", "c", []byte("s"), math.MaxInt64 - 86399},
	}
	for _, tc := range cases {
		if token, err := GenerateSessionCredential(tc.subject, tc.contact, tc.secret, tc.issued); err == nil || token != "" {
			t.Fatalf("invalid generation returned %q, %v", token, err)
		}
	}
	if _, err := GenerateSessionCredential("s", "c", []byte("s"), math.MaxInt64-86400); err != nil {
		t.Fatalf("largest non-overflowing issuedAt rejected: %v", err)
	}
}

func TestVerifySessionCredentialRejectsMalformedTokens(t *testing.T) {
	secret := []byte("secret")
	valid, err := GenerateSessionCredential("s", "c", secret, 10)
	if err != nil {
		t.Fatal(err)
	}
	parts := strings.Split(valid, ".")
	badSignature := parts[0] + "." + base64.RawURLEncoding.EncodeToString(make([]byte, sha256.Size))
	cases := []struct {
		name   string
		token  string
		secret []byte
	}{
		{"empty secret", valid, nil},
		{"no separator", parts[0], secret},
		{"too many segments", valid + ".extra", secret},
		{"invalid payload base64", "*.*", secret},
		{"invalid signature base64", parts[0] + ".*", secret},
		{"wrong signature", badSignature, secret},
		{"wrong secret", valid, []byte("other")},
		{"invalid JSON", signRawPayload(t, []byte("{"), secret), secret},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if _, err := VerifySessionCredential(tc.token, tc.secret, 10); err == nil {
				t.Fatal("malformed token accepted")
			}
		})
	}
}

func TestVerifySessionCredentialRejectsInvalidClaimsJSON(t *testing.T) {
	secret := []byte("secret")
	validClaims := SessionClaims{Subject: "s", Contact: "c", IssuedAt: 10, ExpiresAt: 86410}
	validJSON, err := json.Marshal(validClaims)
	if err != nil {
		t.Fatal(err)
	}
	cases := []struct {
		name    string
		payload []byte
	}{
		{"unknown field", []byte(`{"sub":"s","contact":"c","iat":10,"exp":86410,"extra":1}`)},
		{"trailing JSON", append(append([]byte(nil), validJSON...), []byte(` {}`)...)},
		{"empty subject", []byte(`{"sub":"","contact":"c","iat":10,"exp":86410}`)},
		{"empty contact", []byte(`{"sub":"s","contact":"","iat":10,"exp":86410}`)},
		{"negative issued", []byte(`{"sub":"s","contact":"c","iat":-1,"exp":86399}`)},
		{"wrong expiration", []byte(`{"sub":"s","contact":"c","iat":10,"exp":86411}`)},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			token := signRawPayload(t, tc.payload, secret)
			if _, err := VerifySessionCredential(token, secret, 10); err == nil {
				t.Fatal("invalid claims accepted")
			}
		})
	}
}

package solution

import "testing"

func TestReviewSignatureNewline0276(t *testing.T) {
	secret := []byte("review-secret")
	token, err := GenerateSessionCredential("subject", "contact", secret, 0)
	if err != nil { t.Fatal(err) }
	if _, err = VerifySessionCredential(token+"\n", secret, 1); err == nil { t.Fatal("accepted newline outside unpadded URL-safe base64 alphabet") }
}

